import{c as s,Q as t,j as o,m as a}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"Classes and courses","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/classes-and-courses.md","filePath":"user/event-setup/classes-and-courses.md"}'),n={name:"user/event-setup/classes-and-courses.md"};function r(i,e,l,c,h,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="classes-and-courses" tabindex="-1">Classes and courses <a class="header-anchor" href="#classes-and-courses" aria-label="Permalink to &quot;Classes and courses&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers defining the competition structure.</p><p><em>Classes</em> are the categories competitors enter (e.g. <em>M21A</em>, <em>W14</em>, <em>Open Moderate</em>). <em>Courses</em> are the physical sequences of controls. Classes determine who runs against whom; courses determine what they run.</p><p>This page covers what they are, how they&#39;re related, and how to create, edit, and delete them in Manager. Most events get their classes and courses from an import — see <a href="./import-event-data">Importing event data</a> — so usually you&#39;re reviewing and adjusting rather than entering from scratch.</p><h2 id="how-classes-and-courses-relate" tabindex="-1">How classes and courses relate <a class="header-anchor" href="#how-classes-and-courses-relate" aria-label="Permalink to &quot;How classes and courses relate&quot;">​</a></h2><p>A class can be assigned <strong>one or more courses</strong>, and a course can be assigned to <strong>one or more classes</strong> — the relationship is many-to-many. In practice you&#39;ll see two common patterns:</p><ul><li><strong>One course per class</strong> — typical of championship classes (M21A → &quot;Hard 1&quot; course).</li><li><strong>Multiple classes sharing one course</strong> — typical of age-group classes that all run the same physical course (M21A and W21A both run &quot;Hard 1&quot;). Each class still appears separately on Leaderboard.</li></ul><p>Manager doesn&#39;t require every class to have a course assigned during setup, but a class without a course can&#39;t produce results. The Classes page flags missing assignments so you can spot them at a glance.</p><h2 id="the-classes-page" tabindex="-1">The Classes page <a class="header-anchor" href="#the-classes-page" aria-label="Permalink to &quot;The Classes page&quot;">​</a></h2><p>Navigate to <strong>Classes</strong> in the <strong>Event Data</strong> section of the side menu.</p><p>The table shows one row per class with these columns (some appear conditionally):</p><ul><li><strong>Class</strong> — the class name. Click to open the edit dialog.</li><li><strong>Mass Start</strong> — the class&#39;s mass-start time, if set. Only shown if the event or any class uses a mass start.</li><li><strong>Courses</strong> — the courses assigned to this class.</li><li><strong>Radio Controls (including priority)</strong> — which radio controls report for this class. For relay classes the list is grouped by leg.</li><li><strong>Competitors</strong> — entry count. Only shown if the event is not a relay.</li><li><strong>Teams</strong> — team count. Only shown if the event is a relay.</li><li><strong>On Course</strong> — how many competitors in this class are still On Course (started but not finished).</li></ul><p>Filter the table with <strong>Search by class name</strong> or by <strong>Radio control code</strong>.</p><p>The <strong>Actions</strong> menu (top right) has:</p><ul><li><strong>Import</strong> — open the <strong>Import Data</strong> dialog. See <a href="./import-event-data">Importing event data</a>.</li><li><strong>Add</strong> — create a new class.</li><li><strong>Assign Courses</strong> — bulk-assign courses to classes (see <a href="#assigning-courses-to-classes">Assigning courses to classes</a> below).</li></ul><h2 id="the-courses-page" tabindex="-1">The Courses page <a class="header-anchor" href="#the-courses-page" aria-label="Permalink to &quot;The Courses page&quot;">​</a></h2><p>Navigate to <strong>Courses</strong> in the <strong>Event Data</strong> section.</p><p>The table shows one row per course:</p><ul><li><strong>Course</strong> — the course name. Click to open the edit dialog.</li><li><strong>Controls</strong> — the ordered sequence of control codes. A red warning appears if a course has no controls.</li><li><strong>Length</strong> — the course length in km. Click to open a per-leg breakdown. Normally measured automatically as the sum of the leg distances (shows <code>--</code> if any leg distance is unknown); a ruler icon marks a course whose length has been <strong>set manually</strong> instead.</li><li><strong>Assigned Classes</strong> — count of classes that use this course. Click to see the list.</li></ul><p>Filter with <strong>Search by course name</strong> or by <strong>Control code</strong>.</p><p>The <strong>Actions</strong> menu has:</p><ul><li><strong>Import</strong> — open the <strong>Import Data</strong> dialog.</li><li><strong>Add</strong> — create a new course.</li><li><strong>Assign to Classes</strong> — bulk-assign courses to classes (same dialog as on the Classes page).</li><li><strong>Combine into Variations</strong> — fold several courses that are really forks of one course into a single course with variations (see <a href="#combining-forked-courses-into-variations">Combining forked courses into variations</a> below).</li><li><strong>Leg distances</strong> — open the shared leg-distances editor (see <a href="#leg-distances">Leg distances</a> below).</li></ul><h2 id="creating-a-class-by-hand" tabindex="-1">Creating a class by hand <a class="header-anchor" href="#creating-a-class-by-hand" aria-label="Permalink to &quot;Creating a class by hand&quot;">​</a></h2><p>Click <strong>Actions → Add</strong> on the Classes page. The <strong>Edit Class</strong> dialog opens.</p><p><strong>Fields:</strong></p><ul><li><strong>Class ID</strong> — auto-assigned; read-only.</li><li><strong>Class Name</strong> — required. The name shown everywhere (Leaderboard, start lists, results).</li><li><strong>Short Name</strong> — optional. A shorter label used where space is tight.</li><li><strong>Courses</strong> — multi-select chips. Pick one or more courses for this class, or leave empty and assign later.</li></ul><p><strong>Start time section:</strong></p><ul><li><strong>Class mass start</strong> — toggle on if this class starts together at a fixed time. When on, set <strong>Class Mass Start Time</strong> (defaults to 10:00:00 the first time you enable it).</li><li><strong>Exclude this class from event mass start</strong> — appears only when the event has a mass start and this class doesn&#39;t have its own class mass start. Tick it if this class should start individually despite the event-wide mass start.</li></ul><p>Click <strong>Save</strong>.</p><h2 id="creating-a-course-by-hand" tabindex="-1">Creating a course by hand <a class="header-anchor" href="#creating-a-course-by-hand" aria-label="Permalink to &quot;Creating a course by hand&quot;">​</a></h2><p>Click <strong>Actions → Add</strong> on the Courses page. The <strong>Edit Course</strong> dialog opens with three tabs.</p><h3 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h3><ul><li><strong>Course ID</strong> — auto-assigned; read-only.</li><li><strong>Course Name</strong> — required.</li><li><strong>Course Information</strong> — optional free-text notes (course-setter notes, terrain notes, etc.).</li><li><strong>Start</strong> — which Start this course uses. An event can have several Starts (e.g. &quot;Main Start&quot;, &quot;Easy Courses Start&quot;) at different locations; pick the one this course uses.</li><li><strong>Finish</strong> — which Finish control this course chains through, chosen the same way.</li><li><strong>Controls</strong> — the ordered sequence of <em>middle</em> controls between the Start and the Finish.</li></ul><p>To build the control sequence, type a control code (31–511) into the input and press <strong>Enter</strong>. Each control appears as a chip in the order added. Drag chips to reorder. Click the close icon on a chip to remove it, or press <strong>Backspace</strong> to delete the last one.</p><blockquote><p><strong>Note:</strong> The <strong>Start</strong> and <strong>Finish</strong> are picked from the event&#39;s Start and Finish controls in the dropdowns above — the <strong>Controls</strong> field holds only the middle controls between them. An event can define multiple Start and Finish controls; see <a href="./controls-and-radio-controls">Controls and radio controls</a>.</p></blockquote><h3 id="climb" tabindex="-1">Climb <a class="header-anchor" href="#climb" aria-label="Permalink to &quot;Climb&quot;">​</a></h3><ul><li><strong>Total climb</strong> — total elevation gain over the whole course, in meters.</li></ul><h3 id="length" tabindex="-1">Length <a class="header-anchor" href="#length" aria-label="Permalink to &quot;Length&quot;">​</a></h3><p>Choose how this course&#39;s length is worked out:</p><ul><li><strong>Measured automatically</strong> — the length is the sum of the course&#39;s leg distances (the default), shown beside the option.</li><li><strong>Manually calculated</strong> — enter the length in metres yourself. Use this for <em>sprint</em> courses, where the published length is the shortest sensible route around obstacles rather than the straight-line geometry, or whenever you need a deliberate figure (taped routes, remeasurement). A manual length must be a whole number of metres greater than zero. The value you set here is what Manager publishes to exports (Eventor / IOF XML) and printed splits, in place of the measured sum.</li></ul><p>Below the length options is a read-only breakdown of the distance between each consecutive pair of controls on this course. Leg distances are shared across the whole event, keyed by the two controls&#39; identities — if two courses both go from control 31 → 32 the same distance applies, but a leg from &quot;Start 1 → 131&quot; stays distinct from &quot;Start 2 → 131&quot;. Edit them via <strong>Actions → Leg distances</strong> on the Courses or Controls page.</p><p>If the course has no controls yet, the breakdown tells you to add them on <strong>Details</strong> first.</p><p>Click <strong>Save</strong>.</p><h2 id="assigning-courses-to-classes" tabindex="-1">Assigning courses to classes <a class="header-anchor" href="#assigning-courses-to-classes" aria-label="Permalink to &quot;Assigning courses to classes&quot;">​</a></h2><p>Often you don&#39;t need to assign anything by hand: an <a href="./import-event-data#course-data-iof-coursedata-xml">imported course file</a> that includes class-course assignments (<code>ClassCourseAssignment</code> entries — exported by Purple Pen, OCAD and others) sets each named class&#39;s courses automatically during the import, even when the course names (&quot;Course 1&quot;) don&#39;t match the class names (&quot;M21E&quot;). After a course import, the bulk dialog below opens automatically only if at least one class is still without a course.</p><p>When you do need to assign manually, there are two ways:</p><ul><li><strong>One class at a time</strong> — open the class&#39;s edit dialog and pick courses in the <strong>Courses</strong> field.</li><li><strong>Bulk</strong> — use <strong>Assign Courses</strong> (on the Classes page) or <strong>Assign to Classes</strong> (on the Courses page). Both open the same dialog.</li></ul><p>In the bulk dialog you see one row per class with a multi-select for its assigned courses. Edit any row, then click <strong>Save</strong> — only the changed rows are written, and a counter at the bottom shows how many.</p><p><strong>Auto-assign</strong> (top of the dialog) matches each class to a course by name and fills in the suggestions. After auto-assign, an alert tells you how many classes matched and how many didn&#39;t — review the highlighted rows, edit anything that&#39;s wrong, then <strong>Save</strong>. Useful right after an import that brought in classes and courses with matching names.</p><h2 id="combining-forked-courses-into-variations" tabindex="-1">Combining forked courses into variations <a class="header-anchor" href="#combining-forked-courses-into-variations" aria-label="Permalink to &quot;Combining forked courses into variations&quot;">​</a></h2><p>A forked course — a butterfly, or a relay course where different runners take the loops in different orders — is <em>one</em> course in Manager, carrying a <strong>variation</strong> per fork combination. Each variation has the letter code the course setter printed on the maps (&quot;BDAC&quot;) and its own control sequence.</p><p>Course-setting software doesn&#39;t always tell Manager that. When the course file groups the forks (IOF <code>CourseFamily</code>), the import folds them for you. When it doesn&#39;t, each fork arrives as a course in its own right and the list ends up with &quot;Course 1 BDAC&quot;, &quot;Course 1 ADBC&quot;, &quot;Course 1 BCAD&quot; and &quot;Course 1 ACBD&quot; side by side, none of them knowing about the others.</p><p><strong>Actions → Combine into Variations</strong> puts them back together.</p><p>The dialog opens with <strong>Detected variation families</strong> at the top: sets of courses whose names share a prefix and whose control sequences are alike enough to be forks of one course. Ordinary course numbering (&quot;Course 1&quot;, &quot;Course 2&quot;) isn&#39;t offered, because those courses share no controls. Click <strong>Use</strong> on a family and the selection, the combined name and each variation code are filled in for you.</p><p>You can also do it by hand — tick any courses in the table, edit the combined name, and edit any variation code. The codes must be unique, and they&#39;re what appear on results and splits, so keep them exactly as printed on the maps.</p><p>When you click <strong>Combine</strong>:</p><ul><li>The <strong>first course</strong> in the list survives. It keeps its course id, its Start and Finish, its climb and its position in the list, and takes the combined name. If the selected courses don&#39;t all share the same Start and Finish, the dialog warns you whose are kept.</li><li>Every other selected course becomes a variation and is then <strong>deleted</strong>. Any manual length it had becomes that variation&#39;s length.</li><li><strong>Classes</strong> that used any of them now point at the combined course. A class that used only some of them is restricted to just those variations; a class that used all of them stays unrestricted.</li><li><strong>Competitors</strong> locked to one of the courses are moved to the combined course and locked to the matching variation — so a runner assigned &quot;Course 1 BDAC&quot; still runs the BDAC fork.</li></ul><p>Leg distances need no attention: they&#39;re banked per control pair for the whole event, so every fork&#39;s measurements survive the fold.</p><p>You can run it again later. If a further fork turns up in a re-import, select the already-combined course together with the new one — the combined course keeps the variations it has and the new one is appended. Only one of the selected courses may already have variations.</p><h2 id="relay-events" tabindex="-1">Relay events <a class="header-anchor" href="#relay-events" aria-label="Permalink to &quot;Relay events&quot;">​</a></h2><p>For relay events, the course list still holds the physical courses (one per leg variant), but leg structure — which leg punches which radio control — is configured on the class via its <a href="./controls-and-radio-controls">Radio Controls</a>, not on the course. The course is just an ordered list of controls; the class decides how those controls are grouped by leg.</p><p>See <a href="./relay-events">Relay events</a> for the full picture.</p><h2 id="leg-distances" tabindex="-1">Leg distances <a class="header-anchor" href="#leg-distances" aria-label="Permalink to &quot;Leg distances&quot;">​</a></h2><p>Leg distances are kept in one shared bank for the event, keyed by the identity of the from-control and to-control (not by control code). This means editing the distance for 31 → 32 once updates every course that traverses that leg — while a leg from &quot;Start 1 → 131&quot; stays distinct from &quot;Start 2 → 131&quot;, since the event can have more than one Start. Editing the middle of a course leaves the surviving legs untouched.</p><p>Open the editor from <strong>Actions → Leg distances</strong> on either the Courses or Controls page. The same dialog is reachable from inside the Edit Course dialog as a read-only <strong>Leg distances</strong> tab.</p><h2 id="editing-after-the-event-has-started" tabindex="-1">Editing after the event has started <a class="header-anchor" href="#editing-after-the-event-has-started" aria-label="Permalink to &quot;Editing after the event has started&quot;">​</a></h2><p>Classes and courses remain fully editable after the event has gone live — Manager doesn&#39;t lock them down. This is intentional: late entries land in classes, and you sometimes need to fix a wrongly-set control sequence mid-event.</p><p>That said, a few changes will affect already-finished competitors:</p><ul><li><strong>Adding, removing, or reordering controls on a course</strong> will re-classify every competitor on that course (anyone who matched the old course may now be Mispunched, and vice versa).</li><li><strong>Removing a course from a class</strong> unassigns it for everyone in that class.</li><li><strong>Renaming a class or course</strong> is safe — it&#39;s just a label change.</li></ul><p>If you must edit a course after competitors have started, do it during a quiet moment and check the Results page afterwards.</p><h2 id="deleting-classes-and-courses" tabindex="-1">Deleting classes and courses <a class="header-anchor" href="#deleting-classes-and-courses" aria-label="Permalink to &quot;Deleting classes and courses&quot;">​</a></h2><p>To delete a class, open its edit dialog and click the red <strong>Delete</strong> button at the bottom-left. Confirm the prompt.</p><p>Deleting a course is the same — open it, click <strong>Delete</strong>, confirm. If the course is assigned to any classes, Manager unassigns it from them automatically.</p><p>Deletion is permanent. There&#39;s no undo.</p><h3 id="deleting-them-all-at-once" tabindex="-1">Deleting them all at once <a class="header-anchor" href="#deleting-them-all-at-once" aria-label="Permalink to &quot;Deleting them all at once&quot;">​</a></h3><p>Both pages offer <strong>Actions → Delete all classes</strong> and <strong>Actions → Delete all courses</strong>, for when an import went in wrong and you want to redo it from an empty list rather than pick the entries off one by one.</p><p>Manager confirms first and lists what else changes:</p><ul><li><strong>Delete all classes</strong> takes each class&#39;s radio controls, start-time settings and course assignments with it. The competitors stay, but they end up with no class and stop being evaluated until you give them one — usually by re-importing the class and entry lists. In a relay event the teams keep pointing at a class that no longer exists, so delete or reassign them too.</li><li><strong>Delete all courses</strong> takes each course&#39;s control sequence and fork variations. The classes stay but are left without a course, so nobody can be evaluated until the courses are back. Controls, and the leg distances measured between them, are untouched.</li></ul><p>Neither can be undone. On a live event, <a href="./../reference/backup-and-restore">back the event up</a> first.</p><h2 id="course-pools-and-locking-a-competitor-to-a-course" tabindex="-1">Course pools and locking a competitor to a course <a class="header-anchor" href="#course-pools-and-locking-a-competitor-to-a-course" aria-label="Permalink to &quot;Course pools and locking a competitor to a course&quot;">​</a></h2><p>A class can hold <strong>more than one course</strong> — a <em>course pool</em>. This is common where a class is split across forked courses, or where several map variants share a class. When a competitor&#39;s card is downloaded, Manager checks it against every course in the class&#39;s pool and records the one that produced the best result.</p><p>Some events allow any course for any competitor in a class, whereas some events <strong>lock</strong> a competitor to a specific course. Only the course locked to a specific competitor is checked against the competitors download.</p><p>To lock a competitor to a course:</p><ol><li>Open the competitor in the <strong>Competitors</strong> list.</li><li>On the <strong>Details</strong> tab, use the <strong>Course</strong> picker (shown only when the competitor&#39;s class has a pool of two or more courses).</li><li>Choose the course to lock them to, or leave it on <strong>Any in the course pool</strong> to let Manager pick the best match automatically.</li></ol><p>When a course is locked:</p><ul><li>The competitor download is checked against <strong>only</strong> that course. If their punches don&#39;t match it, they get a Missing Punch (or DNF) against the locked course — Manager will <strong>not</strong> quietly move them to a different course in the pool.</li><li>The lock is durable: it survives re-downloads, course edits, and class edits. (If you move the competitor to a class whose pool doesn&#39;t contain the locked course, the lock is cleared automatically.)</li><li>When the lock is left on <em>Any</em>, the course the automatic evaluation actually chose is shown read-only as the <strong>Course</strong> on the competitor&#39;s <strong>Result</strong> tab, so you can see which course produced their result.</li></ul><p>Course locks can also be applied in bulk by <a href="./import-event-data#course-data-iof-coursedata-xml">importing an IOF course file</a> that contains per-competitor course assignments.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./import-event-data">Importing event data</a> — the usual way to populate classes and courses</li><li><a href="./controls-and-radio-controls">Controls and radio controls</a> — marking controls as radio controls</li><li><a href="./competitors-clubs-teams">Competitors, clubs and teams</a> — assigning competitors to classes</li><li><a href="./relay-events">Relay events</a> — leg structure and team classes</li><li><a href="./start-times">Start times</a> — class mass starts and individual starts</li></ul>',89)])])}const p=s(n,[["render",r]]);export{g as __pageData,p as default};
